        List<Control> Walk(Control c){var all=new List<Control>{c};foreach(Control child in c.Controls)all.AddRange(Walk(child));return all;}
        async Task Settle(){await idle(250);for(int i=0;i<100&&Field<bool>("busy");i++)await idle(100);}
