        check(strip.Controls.Cast<Control>().Select(c=>c.Top).Distinct().Count()==1&&strip.Controls.Cast<Control>().All(c=>c.Right<=strip.ClientSize.Width),"R1.4.1 all resource filters fit one row at 1380x950");
