        var nodes=store.Graph.Nodes;store.SetTypes([new(nodes[0].Name,nodes[0].Type,"光交箱;机房","可更新"),new(nodes[1].Name,nodes[1].Type,"分纤箱","可更新"),new(nodes[2].Name,nodes[2].Type,"分纤箱","可更新"),new(nodes[3].Name,nodes[3].Type,"光交箱","可更新"),new(nodes[4].Name,nodes[4].Type,"光交箱","可更新"),new(nodes[5].Name,nodes[5].Type,"光终端盒","可更新")]);Call("RefreshData");await Settle();
