        string brandRoot=Path.Combine(output,"brand-fixture");Directory.CreateDirectory(Path.Combine(brandRoot,"程序"));File.Copy(Path.Combine(AppContext.BaseDirectory,"FiberRoute.UiChecks.exe"),Path.Combine(brandRoot,"光路调度智能分析.exe"),true);File.Copy(Path.Combine(AppContext.BaseDirectory,"FiberRoute.UiChecks.exe"),Path.Combine(brandRoot,"程序","FiberRouteR1.exe"),true);File.WriteAllText(Path.Combine(brandRoot,"程序","FiberRouteR1.dll"),"fixture");Directory.CreateDirectory(Path.Combine(brandRoot,"数据"));File.WriteAllText(Path.Combine(brandRoot,"数据","personal.db"),"customer data untouched");string original=Path.Combine(output,"original-brand.png");using(var picture=new Bitmap(120,60)){using(var g=Graphics.FromImage(picture)){g.Clear(Color.Red);g.FillRectangle(Brushes.Blue,60,0,60,60);}picture.Save(original,System.Drawing.Imaging.ImageFormat.Png);}BrandApplication.Install(original,brandRoot);check(File.ReadAllBytes(original).SequenceEqual(File.ReadAllBytes(Path.Combine(brandRoot,"资源","品牌原图.png")))&&File.ReadAllText(Path.Combine(brandRoot,"数据","personal.db"))=="customer data untouched","R1.4.1 original-brand installation preserves the exact PNG bytes and customer data");
        using(var icon=new Icon(Path.Combine(brandRoot,"资源","光路调度智能分析.ico"),32,32))using(var bitmap=icon.ToBitmap())check(bitmap.GetPixel(0,0).A<20&&bitmap.GetPixel(8,16).R>180&&bitmap.GetPixel(24,16).B>180,"R1.4.1 generated icon preserves the full aspect ratio, both sides and transparent padding");
        using(var icon=Icon.ExtractAssociatedIcon(Path.Combine(brandRoot,"光路调度智能分析.exe"))!)using(var bitmap=icon.ToBitmap())check(bitmap.GetPixel(bitmap.Width/4,bitmap.Height/2).R>180&&bitmap.GetPixel(bitmap.Width*3/4,bitmap.Height/2).B>180,"R1.4.1 Windows executable icon resources use the complete original instead of the simplified drawing");
        string standalone=Path.Combine(output,"brand-publisher-only");Directory.CreateDirectory(Path.Combine(standalone,"程序"));File.Copy(Path.Combine(AppContext.BaseDirectory,"FiberRoute.UiChecks.exe"),Path.Combine(standalone,"管理方发布工具.exe"));File.WriteAllText(Path.Combine(standalone,"程序","FiberRoute.Publisher.dll"),"fixture");BrandApplication.Install(original,standalone);check(File.Exists(Path.Combine(standalone,"资源","光路调度智能分析.ico"))&&!File.Exists(Path.Combine(standalone,"光路调度智能分析.exe")),"R1.4.1 the same brand tool also supports the standalone management EXE without installing the main client");
        using var publisher=new PublisherForm(Path.Combine(output,"publisher-preferences.json"));publisher.Show(form);await idle(250);check(publisher.ClientSize.Width>=1080*dpi/96-5,"R1.4.1 publisher EXE scales its window and controls with the display DPI");T P<T>(string name)=>(T)typeof(PublisherForm).GetField(name,Hidden)!.GetValue(publisher)!;
        async Task Click(string caption){Walk(publisher).OfType<Button>().Single(b=>b.Text==caption).PerformClick();await idle(100);for(int i=0;i<200&&P<CancellationTokenSource?>("job")!=null;i++)await idle(50);if(P<CancellationTokenSource?>("job")!=null)throw new Exception("publisher action did not finish: "+caption);}
        string workspace=Path.Combine(output,"publisher-work"),server=Path.Combine(output,"publisher-server");P<TextBox>("work").Text=workspace;P<TextBox>("source").Text=store.Root;P<TextBox>("version").Text="2026-10-27.1";P<TextBox>("url").Text="https://updates.example.test/fiber/";P<TextBox>("destination").Text=server;
        await Click("生成更新包");check(File.Exists(P<TextBox>("package").Text),"R1.4.1 publisher EXE wizard generates a data package without command-line arguments");await Click("保存服务配置");check(File.Exists(Path.Combine(workspace,"client-config","update-service.json")),"R1.4.1 publisher wizard creates client public configuration");P<TabControl>("tabs").SelectedIndex=2;await Click("生成发布清单");P<TabControl>("tabs").SelectedIndex=3;await Click("发布到服务器目录");var config=Updates.LoadConfig(Path.Combine(workspace,"update-service.json"))!;var remote=Updates.VerifyEnvelope(File.ReadAllBytes(Path.Combine(server,"manifest.json")),config.PublicKeyPem);check(remote.Resources?.Version=="2026-10-27.1"&&!File.Exists(Path.Combine(server,"private-key.pem")),"R1.4.1 publisher EXE publishes a signed data channel to the server directory without its signing private key");
        using(var image=new Bitmap(publisher.ClientSize.Width,publisher.ClientSize.Height)){using(var g=Graphics.FromImage(image))g.CopyFromScreen(publisher.PointToScreen(Point.Empty),Point.Empty,publisher.ClientSize);image.Save(Path.Combine(output,"R1.4.1-管理方EXE-实际运行.png"));}publisher.Close();
